#include <WiFi.h>
#include <WebServer.h>
#include <DNSServer.h>

WebServer server(80);
DNSServer dns;

void setup() {
  WiFi.mode(WIFI_AP);
  WiFi.softAP("Device-Setup", "replace-this-pass");
  const IPAddress ip = WiFi.softAPIP();
  dns.start(53, "*", ip);
  server.on("/", []() {
    server.send(200, "text/html",
                "<h1>Device setup</h1><p>Connected locally.</p>");
  });
  server.onNotFound([]() {
    server.sendHeader("Location", "/", true);
    server.send(302, "text/plain", "");
  });
  server.begin();
}

void loop() {
  dns.processNextRequest();
  server.handleClient();
}
